  phone = digits;
} else if (digits.startsWith('549') && digits.length === 14 && digits[3] === '0') {
  phone = '549' + digits.slice(4);
} else if (digits.startsWith('54') && digits.length === 12) {
  phone = '549' + digits.slice(2);
} else if (digits.startsWith('0') && digits.length === 11) {
  phone = '549' + digits.slice(1);
} else if (digits.startsWith('9') && digits.length === 11) {
  phone = '54' + digits;
} else if (digits.length === 10) {
  phone = '549' + digits;
} else {
  phone = '549' + digits;
}

// Group ID + sucursal lookup
const dealer = String(body.dealer || '').trim();

const dealerData = DEALER_GROUP_MAP[dealer] ?? {
  group_id: 255,
  sucursal: "SIN ASIGNAR",
};

return [{
  json: {
    ...body,
    phone_e164: phone,
    group_id: dealerData.group_id,
    sucursal: dealerData.sucursal,
  }
}];

